<?php defined('_JEXEC') or die; use Joomla\CMS\HTML\HTMLHelper; use Joomla\CMS\Router\Route; use Joomla\CMS\Session\Session; ?><div class="container-fluid"><h1>Customer KYC</h1><div class="alert alert-info">Original files use an audited, no-store inline preview. The package exposes no download action.</div><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Customer</th><th>Proof</th><th>Reference</th><th>Status</th><th>Submitted</th><th>Decision</th></tr></thead><tbody><?php foreach($this->items as $item): ?><tr><td><?php echo htmlspecialchars(($item['name']??'').' '.($item['email']??''),ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['document_type'],ENT_QUOTES,'UTF-8'); ?> <a target="_blank" rel="noopener" href="<?php echo Route::_('index.php?option=com_kaarbooking&task=kyc.preview&id='.(int)$item['id'].'&'.Session::getFormToken().'=1'); ?>">Preview</a></td><td><?php echo htmlspecialchars($item['masked_reference'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['status'],ENT_QUOTES,'UTF-8'); ?></td><td><?php echo htmlspecialchars($item['created'],ENT_QUOTES,'UTF-8'); ?></td><td><form action="<?php echo Route::_('index.php?option=com_kaarbooking&task=kyc.decide'); ?>" method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?php echo (int)$item['id']; ?>"><select name="decision" class="form-select form-select-sm"><option value="verified">Verify</option><option value="rejected">Reject</option><option value="resubmission_required">Request resubmission</option></select><input name="reason" required class="form-control form-control-sm" placeholder="Decision reason"><button class="btn btn-primary btn-sm">Save</button><?php echo HTMLHelper::_('form.token'); ?></form></td></tr><?php endforeach; ?><?php if(!$this->items): ?><tr><td colspan="6">No customer KYC submissions.</td></tr><?php endif; ?></tbody></table></div></div>
